Under the a scale invariant loss function $L(t)$, the BEE of $\lambda$ is given by $\delta_0=c_0\frac{S_1}{S_2}$ where $c_0$ is the unique solution of 
		\begin{equation}\label{bae}
			EL'(c_0V)V=0
		\end{equation}
		where $V=\frac{S_1}{\lambda S_2}\sim \frac{p_1}{p_2}F_{p_1,p_2}$ and $L'(\cdot)$ denotes the derivative of the loss function $L(\cdot)$.

\begin{itemize}
			\item [(i)]	Let $L_1(t)=(t-1)^2$. The BEE of $\lambda$ is obtain as $\delta_{01}=\frac{p_2-4}{p_1+2}\frac{S_1}{S_2}$ provide $p_2>4$.
			\item [(ii)] Let $L_2(t)=t-\ln t -1$. Then BEE of $\lambda$ is obtained as $\delta_{02}=\frac{p_2-2}{p_1}\frac{S_1}{S_2}$ provided $p_2>2$.
			\item [(iii)] Let $L_3(t)=t+1/t -2$. Then BEE of $\lambda$ is obtained as $\delta_{03}=\left(\frac{p_2(p_2-2)}{p_1(p_1-2)}\right)^{1/2}\frac{S_1}{S_2}$ provided $p_1,p_2>2$.
		\end{itemize}

By (\ref{3.2}) and the Poisson mixture representation of the noncentral chi-square distribution, conditional on an auxiliary random variable $K\sim \text{Poisson}\left(\frac{\eta}{2}\right),$	we have $T\mid K \sim \sigma_2^2\lambda\,\chi^2_{1+2K}.$	                                                                                                                                                                                                                                                     
	Hence, the risk of the estimator $\delta_{\phi_1}$ is	
	\begin{align*}
		R(\delta_{\phi_1},\sigma_1,\sigma_2)=E^{K,W}E\left[L\left(\psi_1\left(\frac{S_1}{S_1+T}\right)\frac{S_1+T}{S_2\lambda}\right)\Big| K, W\right]=                                                                       
		E^{K,W}E\left[L\left(\phi_1(W)V\right)\Big| K, W\right].
	\end{align*} Since $S_2$ is independent of $S_1$ and $T$ and given $K$, $S_1/(S_1+T)$ is independent of $(S_1+T)$. Define
	\begin{align*}
		R_1(d,\sigma_1,\sigma_2)=E\left(L\left(d V\right)\Big|K=k, W=w\right)
	\end{align*}
	where the conditional density of $V$ given $W=w$ and $K=k$ is 
	\begin{align*}
		f_k(v)\propto v^{\frac{p_1+2k-1}{2}} (v+w)^{-\frac{p_1+p_2+2k+1}{2}}, ~~~ v>0.
	\end{align*}
	The risk function is minimized at $d_k(w)$, where $d_k(w)$ is the unique solution of 
	\begin{align*}
		E\left(L'\left(d_k(w)V\right)V\Big| K=k, W=w\right)=0.
	\end{align*}
	Using Lemma A.2. from \cite{bobotas2010estimation}, we have 
	\begin{align*}
		E\left(L'\left(d_0(w)V\right)V\Big| K=k, W=w\right)&\geq E\left(L'\left(d_0(w)V\right)V\Big| K=0,W=w\right)\\
		&=0= E\left(L'\left(d_k(w)V\right)V\Big| K=k, W=w\right).
	\end{align*}
	Consequently we get $d_k(w)\leq d_0(w)$, where $d_0(w)$ is the unique solution of 
	\begin{align*}
		E\left(L'\left(d_0(w)V\right)V\Big| K=0, W=w\right)=0.
	\end{align*}
	By taking the transformation $x=\frac{v}{w}$ on the integral equation, we get $E\left[L'\left(Xwd_0(w)\right)\right]=0$ with $X \sim \text{Beta} \left(\frac{p_1+3}{2}, \frac{p_1-2}{2}\right)$. Comparing with (\ref{3.3}), we get $\alpha_1=wd_0(w)$. Consider $\phi_{01}(w)=\min\left\{\phi_1(w),d_0(w)\right\}$, then for $P\big(d_0(w)<\phi_1(w)\big)\neq 0$ we get $d_k(w)\leq d_0(w)=\phi_{01}(w)<\phi_1(w)$ on set of positive probability. Hence we get $R_1(\phi_{01},\sigma_1,\sigma_2)<R_1(\phi_1,\sigma_1,\sigma_2)$ which implies $R_1(\delta_{\phi_{01}},\sigma_1,\sigma_2)<R_1(\delta_{\phi_1},\sigma_1,\sigma_2)$. This completes the proof of the result.

	\begin{corollary}
		The risk of the estimator                                                                                                                                                                                        
		$\delta_{S1}=\min\left\{c_0,\frac{\alpha_1}{W} \right\}\frac{S_1}{S_2}$ dominates the BEE $\delta_{0}$ provided $P\left(\frac{\alpha_1}{c_0}<W\right)\neq 0$ holds true.
	\end{corollary}
	We now obtained the corresponding results for special loss functions in the following examples.
	\begin{example}
		\begin{itemize}
			\item [(i)]	For the quadratic loss function $L_1(t)$, the improved estimator is obtained as
			\begin{align*}
				\delta_{S11}=\min\left\{\frac{p_2-4}{p_1+2},\ \frac{p_2-4}{p_1+3}\frac{1}{W}\right\}\frac{S_1}{S_2}=\frac{p_2-4}{p_1+2}\min\left\{ 1,\ \frac{p_2+2}{p_1+3}\frac{1}{W}\right\}\frac{S_1}{S_2}.
			\end{align*}
			\item [(ii)] For the entropy loss function $L_2(t)$, the improved estimator is obtained as
			\begin{align*}
				\delta_{S12}=\min\left\{\frac{p_2-1}{p_1},\ \frac{p_2-2}{p_1+1}\frac{1}{W}\right\}\frac{S_1}{S_2}=\frac{p_2-1}{p_1}\min\left\{ 1,\ \frac{p_1}{p_1+1}\frac{1}{W}\right\}\frac{S_1}{S_2}.
			\end{align*}
			\item [(iii)] Under the symmetric loss function $L_3(t)$, the improved estimator is obtained as
			\begin{align*}
				\delta_{S13}&=\min\left\{\left(\frac{p_2(p_2-2)}{p_1(p_1-2)}\right)^{1/2},\ \left(\frac{p_2(p_2-2)}{(p_1+1)(p_1-1)}\right)^{1/2}\frac{1}{W}\right\}\frac{S_1}{S_2}\\
				&= \left(\frac{p_2(p_2-2)}{p_1(p_1-2)}\right)^{1/2}\min\left\{ 1,\ \left(\frac{p_1(p_1-2)}{(p_1+1)(p_1-1)}\right)^{1/2}\frac{1}{W}\right\}\frac{S_1}{S_2}.
			\end{align*}
		\end{itemize}
	\end{example}























































	We obtained a Stein-type estimator $\delta_{S1}$ whose risk is nowhere larger than that of $\delta_{01}$ under a general loss function $L(t)$. In fact such estimator of $\lambda$	is a member of a more general class of estimator of the form (see \cite{das1992improved})
	\begin{align}\label{st2}
		\delta_{\varphi_2}=\varphi_2(U)\frac{S_1}{S_2}\ \mbox{where} \ U=\frac{\sqrt{n_1n_2}|\bar{Y}|}{\sqrt{S_1}}=\frac{\sqrt{T}}{\sqrt{S_1}}.
	\end{align}
	In the next section we will derive some improved estimator on this class.

\begin{itemize}
			\item [(i)]	For the quadratic loss function $L_1(t)$, the improved estimator is obtained as
			\begin{align*}
				\delta_{S11}=\min\left\{\frac{p_2-4}{p_1+2},\ \frac{p_2-4}{p_1+3}\frac{1}{W}\right\}\frac{S_1}{S_2}=\frac{p_2-4}{p_1+2}\min\left\{ 1,\ \frac{p_2+2}{p_1+3}\frac{1}{W}\right\}\frac{S_1}{S_2}.
			\end{align*}
			\item [(ii)] For the entropy loss function $L_2(t)$, the improved estimator is obtained as
			\begin{align*}
				\delta_{S12}=\min\left\{\frac{p_2-1}{p_1},\ \frac{p_2-2}{p_1+1}\frac{1}{W}\right\}\frac{S_1}{S_2}=\frac{p_2-1}{p_1}\min\left\{ 1,\ \frac{p_1}{p_1+1}\frac{1}{W}\right\}\frac{S_1}{S_2}.
			\end{align*}
			\item [(iii)] Under the symmetric loss function $L_3(t)$, the improved estimator is obtained as
			\begin{align*}
				\delta_{S13}&=\min\left\{\left(\frac{p_2(p_2-2)}{p_1(p_1-2)}\right)^{1/2},\ \left(\frac{p_2(p_2-2)}{(p_1+1)(p_1-1)}\right)^{1/2}\frac{1}{W}\right\}\frac{S_1}{S_2}\\
				&= \left(\frac{p_2(p_2-2)}{p_1(p_1-2)}\right)^{1/2}\min\left\{ 1,\ \left(\frac{p_1(p_1-2)}{(p_1+1)(p_1-1)}\right)^{1/2}\frac{1}{W}\right\}\frac{S_1}{S_2}.
			\end{align*}
		\end{itemize}

\label{thierd}
		Suppose the function $\varphi_2$ satisfies the following conditions.
		\begin{enumerate}
			\item [(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u \rightarrow \infty}\varphi_2(u)=c_0$
			\item [(ii)] $\int_{0}^{\infty} L'(\varphi_2(u)v)vF_0(v,u)dv \geq 0$.
		\end{enumerate}
		Then the risk of the estimator $\delta_{\varphi_2}$ in (\ref{st2}) is smaller than the $\delta_{0}$ under the loss function $L(t)$.

Let RD be the risk difference of $\delta_{0}$ and $\delta_{\varphi_2}$, then we can express RD as
	$$\begin{aligned}
		RD & =E\left\{\int_1^{\infty} \frac{d}{d t}L\left(\varphi_{2}(tu)v\right) d t\right\}\\
		& =E\left\{\int_1^{\infty} L'\left(\varphi_{2}(tu)v\right) \varphi_2^{\prime}\left(tu\right) v ud t\right\}\\
		&=\int_{0}^{\infty}\int_{0}^{\infty}\int_1^{\infty} L'\left(\varphi_{2}(tu)v\right) \varphi_2^{\prime}\left(tu\right) vu f_{k}(v,u)dt du dv.\\
	\end{aligned}$$
	Making the transformation $z=tu$ and put $x=\frac{z}{t}$ we get




		$$\begin{aligned}
			RD

			&=\int_{0}^{\infty}\varphi_2^{\prime}\left(z\right)\int_{0}^{\infty}\int_0^{z} L'\left(\varphi_{2}(z)v\right)  v f_{k}(v,x)dx dz dv.
		\end{aligned}$$
		It can be easily check that $\frac{f_{k}(v,x)}{f_{0}(v,x)}$ is non decreasing in $x$ $\forall~ x>0$, and hence we we have $\frac{F_{k}(v,x)}{F_{0}(v,x)}$ is non decreasing in $x$ for $x>0$. By using Lemma $2.1$ of \cite{kubokawa1994unified} and let $v^{*}=\varphi_2^{-1}$ we get 
		$$\begin{aligned}
			RD & \geq \int_{0}^{\infty}\varphi_2^{\prime}\left(z\right)\frac{F_{k}(v^{*},z)}{F_{0}(v^{*},z)}\int_{0}^{\infty} L'\left(\varphi_{2}(z)v\right) v F_{0}(v,z) dv dz.
		\end{aligned}$$
		Hence, the risk difference is non-negative if 
		$$\begin{aligned}
			\int_{0}^{\infty} L'\left(\varphi_{2}(z)v\right) v F_{0}(v,z) dv&\geq0.
		\end{aligned}$$
		This completes the proof.





		Now, we obtain improved estimators for $\lambda$ under three special loss functions by applying Theorem \ref{thierd} in the subsequent corollaries.
		\begin{corollary}
			Let us assume that the function $\varphi_2(u)$ satisfies the following conditions 
			\begin{enumerate}
				\item[(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u\rightarrow\infty}\varphi_2(u)=\frac{p_2-4}{p_1+2}$
				\item[(ii)] $\varphi_2(u)\geq\varphi_{2}^{*1}(u)$
			\end{enumerate}
			where
			\begin{align*}
				\varphi_{2}^{*1}(u) = \frac{ \left(p_2-4\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+3}{2}}ds}{\left(p_1+3\right)\int_{0}^{u} (1+s^2)^{-\frac{p_1+5}{2}}ds}
			\end{align*} 
			The the risk of the estimator $\delta_{\varphi_2}$ given in (\ref{st2}) is nowhere greater than that of $\delta_{01}$ under the quadratic loss function $L_1(t)$.
		\end{corollary}

		\begin{corollary}
			Under the scale-invariant entropy loss function $L_2(t)$, the risk of the estimator $\delta_{\varphi_2}$ given in (\ref{st2}) is nowhere greater than that of $\delta_{02}$ provided the function $\varphi_2(u)$ satisfies  
			\begin{enumerate}
				\item [(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u\rightarrow\infty}\varphi_2(u)=\frac{p_2-2}{p_1}$
				\item[(ii)] $\varphi_2(u)\geq\varphi_{2}^{*2}(u)$
			\end{enumerate}
			where
			\begin{align*}
				\varphi_{2}^{*2}(u) = \frac{ \left(p_2-2\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+1}{2}}ds}{\left(p_1+1\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+3}{2}}ds}.
			\end{align*} 

		\end{corollary}
		\begin{corollary}
			Suppose the following conditions hold true.  
			\begin{enumerate}
				\item [(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u\rightarrow\infty}\varphi_2(u)=\sqrt{\frac{p_2(p_2-2)}{p_1(p_1-2)}}$
				\item[(ii)] $\varphi_2(u)\geq\varphi_{2}^{*3}(u)$
			\end{enumerate}
			where
			\begin{align*}
				\varphi_{2}^{*3}(u) 
				= \sqrt{\frac{p_2\left(p_2-2\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+1}{2}}ds}{\left(p_1+1\right)\left(p_1-1\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+3}{2}}ds}}.
			\end{align*}
			Then the risk of the estimator $\delta_{\varphi_2}$ given in (\ref{st2}) is nowhere greater than that of $\delta_{03}$ under the scale-invariant symmetric loss function $L_3(t)$. 
		\end{corollary}
		\begin{remark}
			In the above corollaries, we have obtained a call of improved estimators for $L_1(t),~L_2(t)$ and $L_3(t)$. The boundary estimators of this class are obtained as $\delta_{\varphi^{*1}_{2}}$, $\delta_{\varphi^{*2}_{2}}$ and $\delta_{\varphi^{*3}_{2}}$. These estimators are \cite{brewster1974improving} type estimators. 
		\end{remark}

Let us assume that the function $\varphi_2(u)$ satisfies the following conditions 
			\begin{enumerate}
				\item[(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u\rightarrow\infty}\varphi_2(u)=\frac{p_2-4}{p_1+2}$
				\item[(ii)] $\varphi_2(u)\geq\varphi_{2}^{*1}(u)$
			\end{enumerate}
			where
			\begin{align*}
				\varphi_{2}^{*1}(u) = \frac{ \left(p_2-4\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+3}{2}}ds}{\left(p_1+3\right)\int_{0}^{u} (1+s^2)^{-\frac{p_1+5}{2}}ds}
			\end{align*} 
			The the risk of the estimator $\delta_{\varphi_2}$ given in (\ref{st2}) is nowhere greater than that of $\delta_{01}$ under the quadratic loss function $L_1(t)$.

Under the scale-invariant entropy loss function $L_2(t)$, the risk of the estimator $\delta_{\varphi_2}$ given in (\ref{st2}) is nowhere greater than that of $\delta_{02}$ provided the function $\varphi_2(u)$ satisfies  
			\begin{enumerate}
				\item [(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u\rightarrow\infty}\varphi_2(u)=\frac{p_2-2}{p_1}$
				\item[(ii)] $\varphi_2(u)\geq\varphi_{2}^{*2}(u)$
			\end{enumerate}
			where
			\begin{align*}
				\varphi_{2}^{*2}(u) = \frac{ \left(p_2-2\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+1}{2}}ds}{\left(p_1+1\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+3}{2}}ds}.
			\end{align*}

Suppose the following conditions hold true.  
			\begin{enumerate}
				\item [(i)] $\varphi_2(u)$ is non-decreasing function in $u$ and $\lim\limits_{u\rightarrow\infty}\varphi_2(u)=\sqrt{\frac{p_2(p_2-2)}{p_1(p_1-2)}}$
				\item[(ii)] $\varphi_2(u)\geq\varphi_{2}^{*3}(u)$
			\end{enumerate}
			where
			\begin{align*}
				\varphi_{2}^{*3}(u) 
				= \sqrt{\frac{p_2\left(p_2-2\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+1}{2}}ds}{\left(p_1+1\right)\left(p_1-1\right) \int_{0}^{u} (1+s^2)^{-\frac{p_1+3}{2}}ds}}.
			\end{align*}
			Then the risk of the estimator $\delta_{\varphi_2}$ given in (\ref{st2}) is nowhere greater than that of $\delta_{03}$ under the scale-invariant symmetric loss function $L_3(t)$.

\label{d1}
		Let $X$ be a random variable whose distribution depends on $(\theta,\varepsilon )$, where $\theta$ is the parameter of interest and $\varepsilon$ is a nuisance parameter. A statistic $T=T(X;x,\theta,\varepsilon)$ is called a generalized pivotal variable for constructing a generalized confidence interval for $\theta$ if it satisfies the following conditions:
		\begin{itemize}
			\item [(G1)] The distribution of $T(X;x,\theta,\varepsilon)$, for fixed $X=x$, is free from all unknown parameters.
			\item [(G2)] The observed value of $T(X;x,\theta,\varepsilon)$ at $X=x$ is equal to $\theta$, that is, $T(X;x,\theta,\varepsilon)=\theta$, where $\theta$ is the parameter of interest.
		\end{itemize}
